effect.shader:
void main() {
    int n = clamp(int(samples), 4, 32);
    float pulso = 0.5 + 0.5 * sin(acTime * rate * 6.2831853);
    float s = amount * pulso;
    if (s <= 0.0) { fragColor = texture(inputImg, acScreenNorm); return; }

    vec2 p = acScreenNorm - center;
    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 32; i++) {
        if (i > n) break;
        float t = float(i) / float(n);
        vec2 u = center + p * (1.0 - s * t);
        soma += texture(inputImg, u);
    }
    fragColor = soma / float(n + 1);
}
